#include <vector>

using namespace std;

class Solution {
public:
    int kInversePairs(int n, int k) {
        const int MOD = 1e9 + 7;
        vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
        dp[0][0] = 1;

        for (int i = 1; i <= n; ++i) {
            vector<int> prefix(k + 1, 0);
            prefix[0] = dp[i - 1][0];
            for (int j = 1; j <= k; ++j)
                prefix[j] = (prefix[j - 1] + dp[i - 1][j]) % MOD;

            for (int j = 0; j <= k; ++j) {
                dp[i][j] = prefix[j];
                if (j >= i)
                    dp[i][j] = (dp[i][j] - prefix[j - i] + MOD) % MOD;
            }
        }

        return dp[n][k];
    }
};
